**Function**: normalize_coefficients

```c
// C program for the function called normalize_coefficients
// Contains target function implementation and dependency signatures

#include <complex.h>
#include <limits.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
int normalize_coefficients(long double *coeffs, unsigned int degree)
{
    if (coeffs == NULL || degree == 0) {
        return -1;
    }
    if (coeffs[0] == 0.0L) {
        return -1;  // Cannot normalize with zero leading coefficient
    }

    long double leading = coeffs[0];
    for (unsigned int i = 0; i < degree; i++) {
        coeffs[i] /= leading;
    }
    return 0;
}

```

